using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurgeAction", menuName = "Data/Battle/Battle Actions/Purge Action")]
public class PurgeAction : BattleAction
{
	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return diceOwnerEnum == DiceOwnerEnum.PLAYER;
	}

	public override void Cast(GameObject source)
	{
		if (CheckConditionToBeCasted(playerHand: false, (!ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source)) ? DiceOwnerEnum.COMPANION : DiceOwnerEnum.PLAYER))
		{
			if (ReferenceSingleton<GameStateManager>.Instance.CurrentState != ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState)
			{
				ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
			}
			(ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance as DiceInstance).DestroyDiceDisposeAction();
			ReferenceSingleton<MiscOmensHandler>.Instance.WickedsCardOmenAction?.Invoke(source, ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject);
			ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
			ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState();
		}
	}
}
